import java.util.Scanner;
public class index {
    // This is the main method that serves as the entry point for the Java application.
    public static void main(String[] args) {
        // Print a message to the console.
        System.out.println("Programa Calculadora");
        // Create a Scanner object to read input from the console.
        Scanner scanner = new Scanner(System.in);
        // Prompt the user to enter the first number.
        System.out.print("Digite el primer numero: ");
        // Read the first number from the console.
        double num1 = scanner.nextDouble();
        // Prompt the user to enter the second number.
        System.out.print("Digite el segundo numero: ");
        // Read the second number from the console.
        double num2 = scanner.nextDouble();
        // Prompt the user to enter the operation they want to perform.
        System.out.print("Digite a operacion (+, -, *, /): ");
        // Read the operation from the console.
        char operation = scanner.next().charAt(0);
        // Initialize a variable to hold the result of the calculation.
        double result = 0;
        // Use a switch statement to determine which operation to perform based on the user's input.
        switch (operation) {
            case '+':
                // If the operation is addition, add the two numbers.
                result = num1 + num2;
                break;
            case '-':
                // If the operation is subtraction, subtract the second number from the first.
                result = num1 - num2;
                break;
            case '*':
                // If the operation is multiplication, multiply the two numbers.
                result = num1 * num2;
                break;
            case '/':
                // If the operation is division, divide the first number by the second.
                if (num2 != 0) {result = num1 / num2;} else {System.out.println("Error: Division by zero is not allowed.");}
                break;
            default:
                // If an invalid operation is entered, print an error message.
                System.out.println("Operacion no valida");
        }
        // Print the result of the calculation to the console.
        System.out.println("El resultado es: " + result);
        // Close the scanner to free up resources.
        scanner.close();
        // Print a message indicating that the program has finished executing.
        System.out.println("Programa finalizado");
        // Exit the program.
        System.exit(0);
    }
}